import{_ as t,a,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 32 Galileo reborn","description":"学习 形容词前置的 as 让步结构，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 32 Galileo reborn","description":"学习 形容词前置的 as 让步结构，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 形容词前置的 as 让步结构，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 31 The sculptor speaks","link":"/life/english/new-concept/book-4/unit-04/lesson-031"},"next":{"text":"第四册：流利英语 · Lesson 33 Education","link":"/life/english/new-concept/book-4/unit-05/lesson-033"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 31 The sculptor speaks","link":"/life/english/new-concept/book-4/unit-04/lesson-031"},"next":{"text":"第四册：流利英语 · Lesson 33 Education","link":"/life/english/new-concept/book-4/unit-05/lesson-033"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-04/lesson-032.md","filePath":"life/english/new-concept/book-4/unit-04/lesson-032.md"}'),o={name:"life/english/new-concept/book-4/unit-04/lesson-032.md"};function l(s,e,r,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-lesson-32-galileo-reborn" tabindex="-1">第四册：流利英语 · Lesson 32 Galileo reborn <a class="header-anchor" href="#第四册-流利英语-·-lesson-32-galileo-reborn" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 32 Galileo reborn&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>本课通过科学史研究重新审视伽利略形象，重点不是把他简单塑造成孤独英雄，而是比较通俗叙述与更细致的历史解释。训练检查人物、实验和时代背景之间的关系，区分旧有故事与后来修正。语言上使用让步性倒装，承认资料限制后提出仍值得检验的问题。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>theory</td><td>/ˈθɪəri/</td><td>n.</td><td>理论</td><td>test a theory</td></tr><tr><td>observation</td><td>/ˌɒbzəˈveɪʃən/</td><td>n.</td><td>观察</td><td>a careful observation</td></tr><tr><td>challenge</td><td>/ˈtʃælɪndʒ/</td><td>v.</td><td>质疑</td><td>challenge an assumption</td></tr><tr><td>orthodoxy</td><td>/ˈɔːθədɒksi/</td><td>n.</td><td>正统观念</td><td>scientific orthodoxy</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>call into question — 对某事提出质疑</li><li>in the light of — 根据新信息重新考虑</li></ul><h2 id="语法讲解-形容词前置的-as-让步结构" tabindex="-1">语法讲解：形容词前置的 as 让步结构 <a class="header-anchor" href="#语法讲解-形容词前置的-as-让步结构" aria-label="Permalink to &quot;语法讲解：形容词前置的 as 让步结构&quot;">​</a></h2><p>形容词 + as + 主语 + be 可表示“尽管”，如 Limited as the evidence is, it deserves attention。它不同于表示原因的 As the evidence is limited…，语序和逻辑都不同。名词前置也可表让步，单数名词常不带冠词，如 Child as he was…；这种结构较正式。让步只承认前项，不取消后面的主句，但主句仍需独立理由支持，不能借修辞替代证据。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Limited as the evidence is, it gives us a reason to repeat the experiment.</p></blockquote><p>尽管证据有限，它仍给了我们重复实验的理由。</p><p>Limited 前置，as 引导让步；it 指 evidence；主句主张重复检验而不是立即接受结论。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>As the evidence is limited 通常更容易读成“因为证据有限”；要保留让步意思可用 Although 或前置 Limited as。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 Limited，再在 is 后停顿；将同句改用 Although 朗读，核对两种结构表达相同让步关系。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Familiar as the story is, its details still need checking. A later retelling may have simplified the scientist’s methods. We should compare the account with documents from the same period.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为一位科学家的历史传记写三句评议：让步、旧说的限制、查证方式。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>让步不等于接受传说，后两句从叙事简化转向同期材料查证，呼应科学史解释的修正。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>用 although 改写 Limited as the evidence is。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Although the evidence is limited</p><p><strong>解析：</strong> 两者都表达让步。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例建议立刻确认理论还是重复实验？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 重复实验。</p><p><strong>解析：</strong> to repeat the experiment 明确后续行动。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：Unusual ___ the result was, it could still be an error.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> as</p><p><strong>解析：</strong> 形容词前置 as 结构表达让步。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：形容词前置的 as 让步结构。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-031">上一课</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-05/lesson-033">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(o,[["render",l]]);export{u as __pageData,b as default};
